"""Explain shared record storage, hash units and exact matching."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1905': ('같은 칸을 수업 중에는 공책 보관에, 수업 뒤에는 정리표 보관에 쓸 수 있어요. 다만 언제 무엇을 넣는지 약속을 지켜야 해요.', '기록 공간을 공유하는 union과 재사용 대기 순서를 이해합니다.', '참조 수 0 → 검색 목록에서 제거 → RCU 상태표 저장 → 재사용 줄 맨 뒤에 추가를 그리세요.', ['참조 수는 기록을 계속 보관해 달라고 얻은 사용 권리의 수예요. 마지막 권리를 put으로 돌려주어 수가 0이 되면 depot_free_stack이 기록을 재사용 대기 상태로 옮겨요. 이 함수는 기록이 들어 있는 메모리 묶음 전체를 운영체제에 돌려주는 함수가 아니에요.', '먼저 pool_lock 잠금을 잡고 list_del_rcu로 검색 목록의 연결을 제거해요. RCU는 예전에 읽기를 시작한 실행이 자료를 아직 볼 수 있다는 점을 고려하는 방법이에요. 목록에서 뺐다고 모든 실행의 눈앞에서 즉시 사라지는 것은 아니에요.', 'get_state_synchronize_rcu로 나중에 기다림의 완료 여부를 확인할 상태표를 얻고 rcu_state에 적어요. 여기서 cookie는 그 상태표를 뜻해요. 지금 함수가 끝날 때까지 모든 읽기의 종료를 기다리는 것은 아니에요. 재사용할 때 별도 함수가 이 상태표로 완료 여부를 물어요.', '기록의 entries는 호출 위치 배열이고 free_list와 rcu_state는 재사용 관리 정보예요. C의 union은 여러 항목이 같은 메모리 자리를 겹쳐 쓰게 해요. 두 용도의 공간을 따로 늘 마련하지 않아도 되지만, 한쪽 값을 쓰면 다른 쪽의 옛 내용은 유지된다고 믿을 수 없어요.', '이 구현은 참조 수가 0인 재사용 대기 상태에서 관리 정보를 써요. 다시 유효한 기록이 되어 참조 수가 0이 아니면 관리 정보를 건드리지 않는 약속을 지켜요. 오래된 검색과 겹칠 가능성은 참조 수 확인과 RCU 규칙까지 함께 다뤄요. union 자체가 동시 사용을 안전하게 만들어 주지는 않아요.', 'list_add_tail은 재사용 줄의 맨 뒤에 붙이는 명령이에요. 먼저 돌아온 기록을 앞에 두어 기다림이 끝났을 가능성이 큰 것부터 살펴요. 검색 목록 연결인 hash_list는 union 밖의 별도 칸이고, 재사용 연결인 free_list와 같은 연결이 아니에요.'], [('호출 위치 배열과 재사용 관리 정보가 같은 union 공간을 써도 되는 핵심 약속은 무엇인가요?', ['사용 중에도 두 정보를 마음대로 번갈아 덮어써요', '참조 수 0인 대기 상태에서 관리 정보를 쓰고 수명 규칙을 지켜요'], '정답은 두 번째예요. 같은 공간을 공유하면 옛 내용이 덮일 수 있어요. 어떤 상태에서 어떤 정보가 유효한지 정한 약속과 RCU 재사용 규칙을 함께 지켜야 해요.'), ('돌려받은 기록은 재사용 목록의 어디에 붙이나요?', ['맨 뒤인 tail에 붙여요', '언제나 맨 앞에 끼워 넣어요'], '정답은 첫 번째예요. 먼저 돌아온 기록이 앞에 남아 먼저 검사받아요. 맨 앞에 계속 새 기록을 넣으면 오래된 것부터 살피려는 순서가 깨져요.')]), 'os1906': ('물건 3개의 무게를 잰 뒤 4그램 묶음으로 나눈다면 물건 개수와 묶음 개수는 달라요. 해시에 넘길 때도 항목 수와 바이트 수를 구분해야 해요.', '호출 위치 수를 jhash2 입력 단위로 바꾸는 계산을 이해합니다.', '항목 하나가 8바이트인 경우 3개×8바이트=24바이트, 24÷4=6개 u32라고 써 보세요.', ['hash는 여러 값을 계산해 만든 검색용 요약 숫자예요. 같은 기록을 찾을 때 후보를 줄이는 데 써요. 서로 다른 내용도 같은 요약 숫자를 만들 수 있는데 이를 충돌이라고 해요. 그래서 hash가 같아도 실제 내용을 다시 비교해야 해요.', 'hash_stack은 호출 위치를 담은 unsigned long 배열을 jhash2라는 계산 함수에 넘겨요. unsigned long의 크기는 환경에 따라 달라요. 이 수업에서는 한 항목이 8바이트인 환경을 가정해요. 바이트는 메모리 크기의 단위예요.', 'jhash2는 입력을 u32 단위로 받아요. u32는 32비트, 즉 4바이트 정수예요. 코드의 array_size(size, sizeof(*entries))는 항목 개수에 한 항목의 바이트 크기를 곱해 전체 바이트 수를 구하고, 이를 sizeof(u32)로 나눠 입력 단위 개수를 만들어요.', '따라서 호출 위치 3개는 3×8=24바이트이고, 24÷4=6개의 u32 단위예요. unsigned long이 4바이트인 환경이면 3×4÷4=3개가 돼요. 원래 항목이 3개라는 이유만으로 jhash2 길이도 항상 3이라고 생각하면 안 돼요.', '(u32 *)entries는 같은 메모리 시작 주소를 u32 단위로 읽도록 표현을 바꾸는 C 코드예요. 새 배열을 만들거나 원래 위치 값을 한 개씩 작은 정수로 잘라 새로 복사하는 명령은 아니에요. STACK_HASH_SEED는 요약 계산의 출발값으로 넘기는 정해진 숫자예요.', '연습에서 모든 입력의 hash를 일부러 같은 수로 정하면 충돌 뒤 실제 내용 비교가 필요한 이유를 볼 수 있어요. 하지만 그것은 jhash2가 어떻게 값을 섞는지나 실제 충돌 빈도를 시험한 것이 아니에요. 입력 단위 계산, 실제 요약 알고리즘, 충돌 뒤 비교는 각각 구별해서 이해해요.'], [('unsigned long 하나가 8바이트인 환경에서 호출 위치 3개는 jhash2의 u32 입력 몇 개 분량인가요?', ['3바이트예요', '6개예요'], '정답은 두 번째예요. 3×8=24바이트이고 u32 하나는 4바이트이므로 24÷4=6개예요. 3바이트라는 답은 항목 개수와 바이트 크기를 섞은 계산이에요.'), ('연습에서 모든 hash를 같은 수로 만들면 실제 jhash2의 충돌 빈도까지 검증한 것인가요?', ['아니요. 충돌한 뒤 실제 내용을 구별하는 과정만 연습한 거예요', '네. 실제 알고리즘의 값 분포와 성능도 증명해요'], '정답은 첫 번째예요. 요약 계산을 일부러 같은 수로 바꿨으므로 실제 알고리즘이 얼마나 고르게 분포시키는지는 알 수 없어요. 실험에서 바꾼 조건을 기억해야 해요.')]), 'os1907': ('두 줄의 번호를 앞에서부터 나란히 확인해요. 이 비교에서는 어느 쪽이 더 큰지보다 똑같은 순서인지가 중요해요.', '전용 비교 함수의 0·1 반환과 빈 범위의 뜻을 이해합니다.', '[10,20]과 [10,20]은 0, [10,20]과 [10,30]은 1, 비교 개수 0이면 0이라고 적으세요.', ['stackdepot_memcmp는 두 호출 위치 배열이 같은지 확인하는 작은 함수예요. u1과 u2는 비교할 배열의 현재 위치를 가리키고 n은 확인할 항목 개수예요. 한 항목은 unsigned long 값이며 바이트 하나씩 비교하는 코드가 아니에요.', '반복문 안에서 *u1과 *u2를 읽어 하나라도 다르면 즉시 1을 돌려줘요. 같으면 u1++과 u2++로 각각 다음 항목에 가요. 끝까지 다른 항목을 찾지 못하면 0을 돌려줘요. 1은 다름, 0은 같음을 뜻하는 이 함수의 약속이에요.', '[10,20]과 [10,30]은 두 번째 항목이 달라 1이에요. [10,30]과 [10,20]처럼 좌우를 바꿔도 1이에요. 1이 왼쪽 숫자가 더 크다는 뜻은 아니에요. 크고 작음에 따라 음수·양수를 구분하는 일반 memcmp의 약속과 혼동하지 마세요.', '호출 경로는 순서도 중요해요. [10,20]과 [20,10]에는 같은 숫자들이 있지만 첫 항목부터 다르므로 1이에요. 함수 호출 순서가 다른 기록을 같은 것으로 합치지 않도록 배열을 임의로 정렬하지 않아요.', 'n이 0이면 비교할 항목이 없어요. 반복 조건 n--는 줄이기 전 값을 조건으로 쓰므로 처음 값 0은 거짓이 되어 본문에 들어가지 않아요. 배열 항목을 읽지 않고 마지막의 0을 반환해요. 이는 빈 비교 범위의 결과이지 두 배열의 모든 내용이 같다는 보장이 아니에요.', '호출한 find_stack은 결과가 1이면 다른 후보로 넘어가고 0이면 다음 조건을 확인해요. 원문은 이 함수를 추가 계측 없는 비교 경로로 설명해요. 계측은 실행을 관찰하려 코드를 덧붙이는 일이에요. 여기서 배울 핵심은 사용처에 맞게 같음 여부만 돌려준다는 점이에요.'], [('이 함수가 1을 돌려줬어요. 왼쪽 배열이 오른쪽보다 크다는 뜻인가요?', ['네. 언제나 크고 작은 순서를 알려줘요', '아니요. 비교한 항목 중 다른 것이 있다는 뜻이에요'], '정답은 두 번째예요. 값이 큰 쪽을 좌우 어느 쪽에 놓든 다르면 1이에요. 이 함수는 정렬 순서가 아니라 같음 여부를 확인해요.'), ('비교할 항목 수 n이 0이면 반환값은 무엇인가요?', ['0이에요', '반드시 1이에요'], '정답은 첫 번째예요. 반복문 본문에서 아무 항목도 읽지 않고 마지막 return 0으로 가요. 이 결과는 비교 범위가 비었다는 조건에서 나온 것이므로 전체 배열이 같다고 확대하면 안 돼요.')]), 'os1908': ('같은 이름표만 보고 물건을 빌리면 다른 물건일 수 있어요. 이름표와 크기, 실제 내용, 지금 빌릴 수 있는 상태까지 차례로 확인해요.', '검색 후보의 내용 확인과 사용 권리 확보를 나누어 이해합니다.', 'hash 다름 → 제외, 길이 다름 → 제외, 내용 다름 → 제외, GET 권리 확보 실패 → 제외의 네 관문을 그리세요.', ['find_stack은 한 검색 묶음인 bucket 안에서 원하는 기록을 찾아요. 먼저 hash라는 요약 숫자와 size라는 항목 수를 확인해요. 둘 중 하나라도 다르면 continue로 다음 후보로 가요. 짧은 숫자 비교로 맞지 않는 후보를 먼저 제외하는 것이에요.', '두 숫자가 맞아도 실제 호출 위치 배열을 stackdepot_memcmp로 비교해요. 요약 숫자가 우연히 같은 충돌이 있을 수 있기 때문이에요. 예를 들어 같은 hash, 길이 2인 [10,20]과 [10,30]은 실제 내용이 다르므로 같은 기록이 아니에요.', '내용까지 같고 GET 옵션을 쓰면 refcount_inc_not_zero로 사용 권리를 얻으려 해요. 보통의 살아 있는 기록에서 참조 수 2라면 3으로 늘어날 수 있어요. 이미 0이면 증가에 실패하므로 그 후보를 반환하지 않고 계속 찾아요. 오래된 기록을 0에서 억지로 되살리지 않는 약속이에요.', '이때 0인지 확인하는 일과 증가하는 일은 하나의 참조 수 연산으로 묶여 있어요. 따로 확인한 뒤 나중에 증가하면 사이에 다른 실행이 마지막 권리를 돌려줄 수 있기 때문이에요. 단순히 숫자가 같다는 사실과 지금 기록을 사용할 권리를 얻었다는 사실은 달라요.', '검색은 rcu_read_lock_sched_notrace와 대응하는 unlock 사이에서 해요. RCU는 오래된 읽기를 고려해 자료 수명을 관리하고, notrace 경로는 추적 도구가 이 동작을 다시 추적하며 되풀이되는 일을 고려한 선택이에요. GET이 없으면 이 함수의 참조 수 증가를 건너뛰며, 그런 사용에서는 나중에 put을 섞지 않는 약속이 필요해요.', '조건을 통과하면 ret에 찾은 기록을 넣고 break로 반복을 끝내요. 후보가 끝까지 없으면 처음 값 NULL을 반환해요. 원문의 data_race 표시는 경쟁 가능성을 의도적으로 다룬다는 표시이며 잠금이나 참조 수 확보를 대신하지 않아요. 종이의 순차 예시는 실제 동시 실행 검증과 구분해요.'], [('GET 검색에서 내용은 같지만 참조 수가 0이라 권리 확보에 실패했어요. 이 후보를 반환하나요?', ['네. 내용이 같으면 무조건 반환해요', '아니요. 다음 후보를 계속 찾아요'], '정답은 두 번째예요. 같은 내용이어도 사용 수명이 끝난 후보일 수 있어요. 코드의 continue는 권리 확보에 실패한 후보를 건너뛴다는 뜻이에요.'), ('실제 호출 위치 배열을 비교하기 전에 먼저 확인하는 두 값은 무엇인가요?', ['요약 숫자 hash와 항목 수 size예요', '사용자 주소와 인터럽트 번호예요'], '정답은 첫 번째예요. 코드가 먼저 비교하는 필드는 hash와 size예요. 두 값이 맞아도 충돌을 구별하려 실제 배열 비교가 이어져요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_472.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
